(()=>{
const root='/games/penguin-extraction/assets/audio/',gun='guns-freesori/',extra='freesori-extra/';
const map={
 'ammo-9':[gun+'shot3.mp3',.78,1,0], 'ammo-45':[gun+'shot3.mp3',.88,.9,0],
 'ammo-57':[gun+'auto2.mp3',.52,1.1,1], 'ammo-556':[gun+'auto1.mp3',.82,1,1],
 'ammo-762':[gun+'shot4.mp3',1.18,.97,0], 'ammo-300':[gun+'shot5.wav',1.25,.88,0],
 'ammo-50':[gun+'shot5.wav',1.38,.74,0], 'ammo-12':[gun+'shotgun2.wav',1.08,.95,0]
};
const files=[gun+'shot1.mp3',gun+'shot3.mp3',gun+'shot4.mp3',gun+'shot5.wav',gun+'auto1.mp3',gun+'auto2.mp3',gun+'shotgun2.wav',gun+'reload.mp3',gun+'explosion5.wav',extra+'footsteps-stairs.wav',extra+'pan-hit.mp3',extra+'blade-hit-1.mp3',extra+'blade-hit-2.mp3',extra+'blade-hit-3.mp3',extra+'password-beep.mp3',extra+'heartbeat-4.mp3',extra+'container-click.wav'];
let ctx,master,muted=false,footAt=0,footIndex=0,heartAt=0,heartIndex=0;const cache=new Map,pending=new Map,seen=new Map,peaks=new Map;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function unlock(){if(!ctx){ctx=new AudioContext;master=ctx.createGain();master.gain.value=muted?0:.34;master.connect(ctx.destination);for(const f of files)load(f)}ctx.resume()}
async function load(f){if(cache.has(f))return cache.get(f);if(pending.has(f))return pending.get(f);const p=fetch(root+f,{credentials:'same-origin'}).then(r=>{if(!r.ok)throw Error(r.status);return r.arrayBuffer()}).then(a=>ctx.decodeAudioData(a)).then(b=>(cache.set(f,b),b)).catch(e=>(console.warn('[audio]',f,e),null)).finally(()=>pending.delete(f));pending.set(f,p);return p}
function onset(b){const d=b.getChannelData(0),step=128,limit=Math.min(d.length,b.sampleRate*2),r=[];let max=0;for(let i=0;i<limit-step;i+=step){let n=0;for(let j=0;j<step;j++){const v=d[i+j];n+=v*v}n=Math.sqrt(n/step);r.push(n);max=Math.max(max,n)}const k=r.findIndex(v=>v>max*.18);return Math.max(0,(k<0?0:k*step)/b.sampleRate-.012)}
function stepPeaks(b){if(peaks.has(b))return peaks.get(b);const d=b.getChannelData(0),step=256,r=[],minGap=Math.floor(b.sampleRate*.2/step);let max=0;for(let i=0;i<d.length-step;i+=step){let n=0;for(let j=0;j<step;j++){const v=d[i+j];n+=v*v}n=Math.sqrt(n/step);r.push(n);max=Math.max(max,n)}const out=[];for(let i=1;i<r.length-1;i++)if(r[i]>max*.24&&r[i]>=r[i-1]&&r[i]>r[i+1]&&(!out.length||i-out[out.length-1]>minGap))out.push(i);const times=(out.length?out:[0]).map(i=>Math.max(0,i*step/b.sampleRate-.025));peaks.set(b,times);return times}
function playFile(f,o={}){if(!ctx||!master||muted)return;const b=cache.get(f);if(!b){load(f).then(x=>x&&playFile(f,o));return}const src=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain(),pan=ctx.createStereoPanner(),now=ctx.currentTime,dist=Math.max(0,o.distance||0),range=o.suppressed?65:210,fall=clamp(1-dist/range,0,1);if(fall<.002)return;src.buffer=b;src.playbackRate.value=(o.pitch||1)*(.99+Math.random()*.02);filter.type=o.suppressed?'lowpass':'highpass';filter.frequency.value=o.suppressed?1750:25;filter.Q.value=.5;gain.gain.setValueAtTime(clamp((o.gain||1)*fall*(o.suppressed?.68:1),.001,1.55),now);pan.pan.value=clamp(o.pan||0,-1,1);src.connect(filter).connect(gain).connect(pan).connect(master);const start=o.offset??(o.trim?onset(b):0),dur=Math.min(b.duration-start,o.duration??(o.trim?.105:1.5));if(dur<=.01)return;if(o.fade)gain.gain.exponentialRampToValueAtTime(.001,now+dur);src.start(now,start,dur);src.stop(now+dur+.02)}
function gunshot(o={}){unlock();if(o.eventKey){const n=performance.now(),v=seen.get(o.eventKey);if(v&&n-v<1500)return;seen.set(o.eventKey,n)}let a=map[o.ammoId]||map['ammo-556'],w=String(o.weaponId||'').toLowerCase();if(w.includes('crossbow'))a=[gun+'shot1.mp3',.86,1,0];else if(w.includes('lynx'))a=[gun+'shotgun2.wav',1.32,.84,0];else if(w.includes('mk14'))a=[gun+'shot5.wav',1.28,.96,0];else if(w.includes('mg3'))a=[gun+'auto2.mp3',.52,.88,1];let pitch=a[2],gain=a[1];if(w.includes('awm')){pitch*=.92;gain*=1.1}playFile(a[0],{gain,pitch,trim:!!a[3],fade:!!a[3],suppressed:!!o.suppressed,distance:o.distance,pan:o.pan})}
function setMuted(value){muted=!!value;if(master)master.gain.value=muted?0:.34}
function reload(){unlock();playFile(gun+'reload.mp3',{gain:.55,duration:2.2})}
function explosion(o={}){unlock();playFile(gun+'explosion5.wav',{gain:1,duration:2.7,distance:o.distance||0,pan:o.pan||0})}
function footstep(moving,sprinting,now=performance.now()){if(!moving){footAt=now;return}const cadence=sprinting?285:420;if(now-footAt<cadence)return;footAt=now;const f=extra+'footsteps-stairs.wav',b=cache.get(f);if(!b){load(f);return}const p=stepPeaks(b),offset=p[footIndex++%p.length];playFile(f,{gain:sprinting?.42:.3,pitch:sprinting?1.06:.96,offset,duration:.2,fade:true})}
function melee(weaponId=''){const w=String(weaponId).toLowerCase();if(w.includes('frying-pan'))playFile(extra+'pan-hit.mp3',{gain:.78,duration:.8});else if(w.includes('sickle')||w.includes('machete')){const n=1+Math.floor(Math.random()*3);playFile(extra+`blade-hit-${n}.mp3`,{gain:.72,duration:.85})}}
function passwordDoor(){playFile(extra+'password-beep.mp3',{gain:.24,duration:1.2})}
function containerOpen(){playFile(extra+'container-click.wav',{gain:.45,duration:.5})}
function heartbeat(hp=100,now=performance.now()){if(hp>=30){heartAt=now;return}const cadence=hp<15?560:760;if(now-heartAt<cadence)return;heartAt=now;const f=extra+'heartbeat-4.mp3',b=cache.get(f);if(!b){load(f);return}const part=b.duration/4,offset=(heartIndex++%4)*part;playFile(f,{gain:hp<15?.48:.36,pitch:hp<15?1.08:1,offset,duration:Math.min(part,.72),fade:true})}
addEventListener('pointerdown',unlock,{capture:true});addEventListener('keydown',unlock,{capture:true});window.__peAudio={gunshot,reload,explosion,footstep,melee,passwordDoor,containerOpen,heartbeat,setMuted,unlock};
})();
